add_filter( 'woocommerce_checkout_fields', 'perfectpixel_address_as_textarea', 9999 );

function perfectpixel_address_as_textarea( $fields ) {
	foreach ( array( 'billing', 'shipping' ) as $group ) {
		$key = $group . '_address_1';
		if ( isset( $fields[ $group ][ $key ] ) ) {
			$fields[ $group ][ $key ]['type']              = 'textarea';
			$fields[ $group ][ $key ]['custom_attributes']['rows'] = 2;
		}
	}
	return $fields;
}
